import openpyxl
wb = openpyxl.load_workbook('1_102-20_answer_template_5012_input.xlsx')
for ws in wb.worksheets:
    print('\nSHEET', ws.title)
    print('dim', ws.dimensions)
    print('max_row', ws.max_row, 'max_col', ws.max_column)
    # print cell styles: fill, border, number_format, protection for all cells
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
        for c in row:
            fill = c.fill
            border = c.border
            nf = c.number_format
            prot = c.protection
            style_desc = []
            if fill.fill_type or (fill.start_color and fill.start_color.rgb):
                style_desc.append(f'fill={fill.patternType}/{fill.start_color.rgb if fill.start_color else None}/{fill.end_color.rgb if fill.end_color else None}')
            bparts=[]
            for side in ['left','right','top','bottom']:
                s=getattr(border,side)
                if s.style:
                    bparts.append(f'{side[0]}:{s.style}')
            if bparts: style_desc.append('border:'+','.join(bparts))
            if nf and nf!='General': style_desc.append(f'nf={nf}')
            if prot and (prot.locked==False or prot.hidden==True): style_desc.append(f'prot=lock:{prot.locked},hidden:{prot.hidden}')
            if style_desc:
                print(c.coordinate, repr(c.value), ' | '.join(style_desc))
