issues=[]
for sn in wbg.sheetnames:
    wi=wbi[sn]; wg=wbg[sn]
    for row in wg.iter_rows():
        for c in row:
            coord=c.coordinate
            vi=wi[coord]
            # compare values / formulas
            if vi.data_type=='f' or c.data_type=='f':
                if vi.value != c.value:
                    issues.append((sn,coord,'formula',repr(vi.value),repr(c.value)))
            else:
                if vi.value != c.value:
                    issues.append((sn,coord,'value',repr(vi.value),repr(c.value)))
            # compare style id
            if vi.style_id != c.style_id:
                issues.append((sn,coord,'style_id',vi.style_id,c.style_id))
            if vi.number_format != c.number_format:
                issues.append((sn,coord,'nf',vi.number_format,c.number_format))
